solutionCode:
public class Solution {
    static class Fenwick {
        private final long[] t;

        Fenwick(int n) { t = new long[n + 1]; }

        // t[i] cobre os lowbit(i) elementos que terminam em i.
        void add(int i, long delta) {
            for (i++; i < t.length; i += i & -i) t[i] += delta;
        }

        long prefixo(int i) {
            long s = 0;
            for (i++; i > 0; i -= i & -i) s += t[i];
            return s;
        }

        long soma(int l, int r) {
            if (l > r) return 0;
            return prefixo(r) - (l == 0 ? 0 : prefixo(l - 1));
        }
    }
}

