import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void pequeno() {
        var f = new Solution.Fenwick(5);
        for (int i = 0; i < 5; i++) f.add(i, i + 1); // [1, 2, 3, 4, 5]
        assertEquals(15, f.prefixo(4));
        assertEquals(9, f.soma(1, 3));
        assertEquals(1, f.soma(0, 0));
        assertEquals(0, f.soma(3, 2));
        f.add(2, -10);
        assertEquals(-1, f.soma(1, 3));
    }

    @Test void aleatorio() {
        var rnd = new Random(18);
        int n = 50;
        long[] a = new long[n];
        var f = new Solution.Fenwick(n);
        for (int op = 0; op < 5000; op++) {
            int i = rnd.nextInt(n);
            if (rnd.nextBoolean()) {
                long d = rnd.nextInt(2_000_000_000) - 1_000_000_000L;
                a[i] += d;
                f.add(i, d);
            } else {
                int j = rnd.nextInt(n);
                long e = 0;
                for (int k = Math.min(i, j); k <= Math.max(i, j); k++) e += a[k];
                assertEquals(e, f.soma(Math.min(i, j), Math.max(i, j)));
            }
        }
    }

    @Test void grande() {
        int n = 200_000;
        var f = new Solution.Fenwick(n);
        for (int i = 0; i < n; i++) f.add(i, 1_000_000_000);
        assertEquals(200_000L * 1_000_000_000, f.prefixo(n - 1));
        assertEquals(1_000_000_000, f.soma(n - 1, n - 1));
    }
}

statement:
Array estático; responda muitas consultas de mínimo em `[l, r]` (inclusivo) em O(1) cada.

## Contrato

```java
static class Sparse {
    Sparse(int[] a);
    int min(int l, int r);
}
```

## Restrições

- `st[k][i]` = mínimo de `[i, i + 2^k)`. Consulta: duas janelas de tamanho `2^k` que se sobrepõem.
- Pré-calcule `log[]` (sem `Math.log`). Até 200 mil elementos e 1 milhão de consultas.

