public class Solution {
    static class Sparse {
        private final int[][] st;
        private final int[] log;

        Sparse(int[] a) {
            int n = a.length;
            log = new int[n + 1];
            for (int i = 2; i <= n; i++) log[i] = log[i / 2] + 1;
            st = new int[log[Math.max(n, 1)] + 1][];
            st[0] = a.clone();
            for (int k = 1; k < st.length; k++) {
                st[k] = new int[n - (1 << k) + 1];
                for (int i = 0; i < st[k].length; i++) st[k][i] = Math.min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
            }
        }

        // min é idempotente: sobrepor as duas janelas não altera o resultado.
        int min(int l, int r) {
            int k = log[r - l + 1];
            return Math.min(st[k][l], st[k][r - (1 << k) + 1]);
        }
    }
}

