import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void pequeno() {
        var s = new Solution.Sparse(new int[]{4, 6, 1, 5, 7, 3});
        assertEquals(1, s.min(0, 5));
        assertEquals(4, s.min(0, 1));
        assertEquals(3, s.min(3, 5));
        assertEquals(7, s.min(4, 4));
    }

    @Test void todosOsIntervalos() {
        var rnd = new Random(19);
        for (int n = 1; n <= 40; n++) {
            int[] a = rnd.ints(n).toArray();
            var s = new Solution.Sparse(a);
            for (int l = 0; l < n; l++) {
                int m = Integer.MAX_VALUE;
                for (int r = l; r < n; r++) {
                    m = Math.min(m, a[r]);
                    assertEquals(m, s.min(l, r));
                }
            }
        }
    }

    @Test void milhaoDeConsultas() {
        int n = 200_000;
        int[] a = new Random(20).ints(n).toArray();
        var s = new Solution.Sparse(a);
        var rnd = new Random(21);
        long acc = 0;
        for (int q = 0; q < 1_000_000; q++) {
            int l = rnd.nextInt(n), r = l + rnd.nextInt(n - l);
            acc += s.min(l, r);
        }
        assertNotEquals(0, acc);
    }
}
